UPDATE companies SET description='Cutlist CO operates a digital fabrication studio in Denver, Colorado, founded in 2006. The company provides CNC routing and laser cutting services to artists, makers, builders, and designers from its Colorado facility.

The shop runs a ShopSabre CNC router equipped with a 12-position automatic tool changer and vacuum hold-down, alongside a pro-series laser cutter and 3D printing capabilities. It processes full 48-by-96-inch sheets of plywood, plastic, and composite materials, delivering 2D profiles, dados, pockets, drill patterns, and laser engraving. Batch production runs of 500 identical parts are routine, and nested sheet optimization reduces waste. Most jobs ship within 10 business days.

Customers range from individual artists creating installation components to small businesses needing 200 identical product parts. The studio serves interior designers building statement pieces, furniture makers producing cabinets and shelving, prototypers developing models and jigs, and retailers requiring signage and display shelving. Materials include Baltic birch, maple, MDF, acrylic, PVC, ABS, foam, cardboard, fabric, and leather.

Cutlist CO distinguishes itself by focusing strictly on cutting—no assembly, finishing, or design work—so clients receive precision parts ready for their own processes. The company sources its own sheet stock to guarantee flatness and machine compatibility, and it maintains a $500 job minimum for CNC routing. The founders built the business on the premise that if you can design it, you should be able to build it locally.', certifications=ARRAY[]::text[], profile='{"capabilities": ["CNC routing (2D profiles, dados, pockets, drill patterns)", "Laser cutting", "Laser engraving", "3D printing", "Nested sheet optimization", "Batch production", "Design-for-manufacturing assistance (file preparation)", "Material sourcing"], "industries": ["Artists and makers", "Builders and designers", "Art installations", "Interior design", "Furniture manufacturing", "Cabinetry", "Prototyping", "Model making", "Jig and fixture fabrication", "Storage and organization products", "Signage and marketing components", "Retail display and shelving"], "materials": ["Baltic birch plywood", "Maple plywood", "Veneer core plywood", "HPL laminated plywood", "Bamboo plywood", "MDF", "Melamine", "Acrylic", "PVC", "ABS", "Foam", "Cardboard", "Paper", "Fabric", "Leather", "Felt", "Composite panels"], "equipment": ["ShopSabre CNC router with 12-position automatic tool changer and vacuum hold-down", "Pro-series laser cutter", "3D printer (unspecified model)"], "volume": "", "lead_time": "10 business days typical", "tolerances": "", "built_on": ["Job minimum $500 for CNC routing services", "Typical turnaround 10 business days", "Material sourcing included to ensure quality and machine compatibility", "ShopSabre CNC router with 12-tool automatic changer and vacuum hold-down", "Cut-only model: no assembly, finishing, or design services"], "facts_used": ["Founded 2006 -> db", "Headquarters Denver, Colorado -> db", "CNC routing and laser cutting services -> /", "ShopSabre CNC router with 12-position ATC and vacuum hold-down -> /services", "Pro-series laser cutter -> /", "3D printing capabilities -> /", "Materials: plywood, plastic, cardboard, fabric, leather, foam -> /", "Job minimum $500 for CNC routing -> /services", "Typical lead time 10 business days -> /", "No assembly, finishing, or design services -> /services", "Customer-supplied material generally not accepted -> /services", "Industries: artists, makers, builders, designers, interior design, furniture, prototyping, signage, retail display -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We''re a CNC and Laser cutting service for people who need parts.", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "$500 job minimum for CNC routing", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='cutlist-co' AND approved AND profile IS NULL;
