UPDATE companies SET description='Dirt Road Steel operates from Riverton, Wyoming, as a veteran-owned and locally operated business. The company emphasizes its American-made roots, though a specific founding year is not publicly disclosed.

The shop produces hand-carved wooden flags and crosses, each made to order, along with upcoming metal art and apparel lines. Every item is described as 100% handmade and handcrafted in the USA, with no automation mentioned. The product range includes patriotic crosses (Old Glory, Thin Blue Line, Thin Red Line, Thin Green Line), wooden flags, and personalized signs such as the Wyoming Home Key Holder and monogrammed gifts.

Customers are primarily individuals seeking patriotic or faith-based gifts for military families, veterans, and first responders. Reviews cite purchases for Christmas, Mother''s Day, and high school graduation gifts for enlistees, with buyers noting the items'' symbolic value for Air Force special forces candidates, law enforcement, and firefighter households.

The company positions its veteran ownership and made-to-order craftsmanship as its core differentiators, highlighting free shipping on all orders and a commitment to 100% domestic production. The focus on unique character in each hand-carved piece and the personal connection to military service underpin its appeal.', certifications=ARRAY['Veteran-owned']::text[], profile='{"capabilities": ["hand carving", "woodworking", "custom wooden flag fabrication", "custom wooden cross fabrication", "made-to-order production"], "industries": ["consumer goods", "home decor", "patriotic gifts", "military/veteran community", "first responder gifts"], "materials": ["wood", "metal"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% handmade and handcrafted in the USA", "Every product made to order", "Veteran-owned and locally operated", "Free shipping on all orders", "Unique character in each hand-carved piece"], "facts_used": ["Company name: Dirt Road Steel -> db", "Location: Riverton, Wyoming -> db", "Veteran-owned certification -> db", "100% hand crafted, handmade, made to order -> page:/", "Products: wooden flags, hand carved crosses, metal art coming soon, apparel coming soon -> page:/", "Free shipping on all orders -> page:/", "Locally owned and operated -> page:/", "100% made in America, handcrafted in USA -> page:/", "Customer reviews indicating gift use for military, first responders -> page:/"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our products are beautifully hand carved. Each of our handmade flags is made to order.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned"]}'::jsonb, updated_at=now() WHERE slug='dirt-road-steel' AND approved AND profile IS NULL;
UPDATE companies SET description='The company was established in 1993 and has served the region''s sheet metal needs for over three decades.

The shop specializes in custom sheet metal fabrication, cutting and bending galvanized steel to produce HVAC ductwork, plenums, transitions, fittings, and a range of one-off parts such as brackets, signs, panels, and covers. It accepts orders from a single piece to production quantities, working from customer drawings, photos, samples, or even rough field sketches. The team also offers field measurement services to verify dimensions before fabrication. Finished parts are typically ready for quick pickup.

Primary customers include HVAC and mechanical contractors who encounter field conditions that don''t match catalog parts, as well as homeowners needing replacement duct fittings or transitions. The company also supports retrofit projects and small-run custom metalwork for a variety of industrial and commercial applications.

Diversified Metal Fabricators distinguishes itself by accepting virtually any form of part definition — from formal prints to marked-up photos — and by delivering fabricated assemblies with mechanical joints that eliminate exposed fasteners. The emphasis on rapid turnaround for pickup and the ability to scope parts in a single conversation are cited as key advantages.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Sheet metal cutting and bending", "HVAC ductwork fabrication", "Plenum and transition fabrication", "Custom fitting fabrication", "Bracket, sign, panel, and cover fabrication", "Field measurement and verification", "Design consultation and spec confirmation", "One-off and low-volume production", "Prototype fabrication", "Mechanical joint assembly (without exposed fasteners)"], "industries": ["HVAC contractors", "Mechanical contractors", "Retrofit construction", "Residential construction", "General custom fabrication"], "materials": ["Galvanized steel"], "equipment": [], "volume": "One-off to production quantities", "lead_time": "", "tolerances": "", "built_on": ["Accepts drawings, photos, samples, or rough sketches for quoting", "Offers field measurement service to confirm dimensions", "No minimum order quantity; runs from one-off to production volumes", "Fabricates parts in premium galvanized steel for quick pickup", "Produces mechanical joints on duct and formed assemblies without exposed fasteners"], "facts_used": ["Founded 1993 -> db", "Headquarters Ferndale, Michigan -> db", "Capabilities: custom fabrication, HVAC fabrication -> db", "Products: custom duct, fittings, one-off parts -> db", "EST. 1993 on homepage -> /", "HQ 2351 Hilton, Ferndale, MI 48220 -> /", "Serves HVAC contractors, custom parts, homeowners -> /", "Accepts drawings, photos, samples, rough sketches -> /", "Field measurement service -> /", "One-off, small run, or production quantity -> /", "Fabricates in premium galvanized steel -> /", "Quick pickup for fabricated parts -> /", "Mechanical joints without exposed fasteners -> /", "Custom parts: brackets, signs, panels, covers -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Custom duct, fittings, and one-off parts when the stock item will not work. Send a drawing or photo.", "founded_year": "1993", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='diversified-metal-fabricators' AND approved AND profile IS NULL;
UPDATE companies SET description='Diversified Plastics, Inc. was founded in 1976 by Rod Reid in Missoula, Montana. The family-owned business began in Reid’s garage as a supplier of engineered plastic wear strips for lumber and pulp mills in the surrounding area. Today the company is led by Reid’s son, Brad Reid, a mechanical engineer, and operates from a 3.5‑acre campus in Missoula that is slated to reach 60,000 square feet of building space by the end of 2025.

The company provides custom plastics fabrication and engineering services, combining injection molding of UHMW‑PE, CNC machining, cast urethane, thermoforming, plastics welding, vacuum forming, overmolding of steel parts, and its proprietary MultiFab hybrid component process under one roof. With more than 60 employees, the facility runs injection molding machines with shot capacities from 19 to 311 ounces, four 80,000‑pound material silos, and a broad CNC lineup that includes HAAS machining centers. Diversified Plastics delivers tens of thousands of parts annually, from prototype quantities to production runs of thousands.

Customers span lumber and pulp processing, industrial wastewater treatment, mining, forest products, oil‑field equipment (such as McClain Oil Tools), grain handling, car‑wash systems, and even local breweries. The company ships to over 15 countries and serves OEMs, maintenance departments, and distributors seeking metal‑to‑plastic conversions, wear‑resistant components, and complex assemblies.

Diversified Plastics differentiates itself through its MultiFab approach, which integrates fabrication, machining, injection molding, and polyurethane casting to reduce lead times and enable single‑source sourcing. Lean production protocols and collaborative, on‑site problem solving have been core to the operation since its garage start.', certifications=ARRAY['ISO procedures']::text[], profile='{"capabilities": ["Injection Molding UHMW-PE", "Injection Molding (general)", "CNC Machining", "Cast Urethane", "Custom Fabrication", "Thermoforming", "Plastics Welding", "Vacuum Forming", "Overmolding of Steel Parts", "QC Testing", "Stamping/Labeling Parts ID", "MultiFab Hybrid Components", "Design Engineering", "Tool and Die Services", "Gear Cutting", "Prototype Tooling", "Molding of Polyureas and Epoxies", "Precision Machining", "Large Diameter Near Net Shape Cast Nylon Parts", "Secondary Operations (vapor polishing, installing inserts, bonding plastic to steel, welding, gluing, forming)", "5th Axis Machining"], "industries": ["Lumber and pulp mills", "Industrial wastewater treatment", "Mining", "Forest products", "Oil and gas equipment", "Grain handling", "Car wash equipment", "Brewing", "Crosslinked components", "Timber processing", "Energy", "Packaging"], "materials": ["UHMW-PE", "Nylon", "Acetal", "Urethane", "Ultem", "PEEK", "HDPE", "Polypropylene", "Filled materials", "Cast nylon", "Polyureas", "Epoxies", "Regrind UHMW"], "equipment": ["HAAS CNC machines"], "volume": "Prototype to production runs (tens to thousands of parts annually)", "lead_time": "", "tolerances": "", "built_on": ["MultiFab technology combining fabrication, machining, injection molding, and polyurethane casting under one roof", "Unique injection molding of UHMW virgin and regrind materials", "Lean production processes and comprehensive project management protocols since 1976", "Single-source vendor for prototype to production volumes"], "facts_used": ["Founded 1976 by Rod Reid in Missoula, Montana -> /about-us", "Family-owned, now led by Brad Reid -> /about-us", "More than 60 employees -> /about-us", "3.5-acre campus, 60,000 sq ft by end of 2025 -> /", "Four 80,000 lbs silos -> /", "Injection molding shot sizes 19-311 oz -> /capabilities", "HAAS CNC machines -> /capabilities", "Tens of thousands of parts per year -> /about-us", "Prototype to production runs (tens to thousands) -> / (testimonial)", "Industries: lumber/pulp, wastewater, mining, forest, oil & gas, grain handling, car wash, brewery -> /about-us, / (testimonials)", "Ships to over 15 countries -> /about-us", "MultiFab technology combining fabrication, machining, injection molding, polyurethane casting -> /about-us", "Unique injection molding of UHMW virgin and regrind -> /about-us", "In-house recycling diverting nearly 250,000 lbs scrap annually -> /about-us", "Lean production protocols since 1976 -> /about-us", "Materials: UHMW-PE, nylon, acetal, urethane, Ultem, PEEK, HDPE, polypropylene, filled materials -> /capabilities", "Capabilities list -> /capabilities, /", "Testimonials from McClain Oil Tools, Crosslinked Components, Montrose Forest Products, Curbell Plastics -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Diversified Plastics Industrial Solutions is a USA manufacturer with 50 years of experience in injection molded UHMW-PE, cast urethane, CNC machining, thermoforming, and custom fabrication.", "founded_year": "1976", "employee_count": "60+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='diversified-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Dominion Steel LLC operates from a 35,000-square-foot fabrication facility in Fredericksburg, Virginia. The company traces its roots to 1994, when it began as a small fabrication shop and has since grown into a full-service steel center serving Virginia, Maryland, and the District of Columbia.

The firm provides turnkey structural steel solutions, handling estimating, detailing, fabrication, and erection in-house. Its capabilities span commercial structural steel, miscellaneous metal fabrication (including stainless steel and aluminum), welding, structural coating, and custom railings and gates. An on-site quality assurance team monitors production from raw material to finished assembly.

Dominion Steel serves general contractors, architects, engineers, and developers across education, healthcare, entertainment, government, and commercial sectors. Projects range from school buildings and hospitals to entertainment venues and government facilities, with the company noting a willingness to take on complex jobs that other shops decline.

The company emphasizes its integrated approach as a differentiator: by consolidating estimating, detailing, fabrication, and erection under one roof, it maintains tight control over quality, scheduling, and cost. Leadership describes a culture of integrity and safety, with a focus on building long-term partnerships through communication and accountability.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Structural steel fabrication", "Steel erection", "Miscellaneous metal fabrication", "Welding services", "Structural coating", "Railings and gates fabrication", "Estimating and detailing", "Engineering and detailing"], "industries": ["Education", "Healthcare", "Entertainment", "Government", "Commercial"], "materials": ["Structural steel", "Stainless steel", "Aluminum"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Turnkey in-house estimating, detailing, fabrication, and erection", "35,000 sq ft fabrication facility with modern equipment", "On-site full-time quality assurance team", "Willingness to execute complex projects other shops avoid", "Regional service across Virginia, Maryland, and D.C."], "facts_used": ["Founded 1994 -> /about", "35,000 sq ft facility -> /about", "Turnkey estimating, detailing, fabrication, erection -> /", "Services: structural steel, miscellaneous metals (stainless, aluminum), welding, structural coating, railings & gates -> /, /about", "Industries: education, healthcare, entertainment, government, commercial -> /about", "Customer types: general contractors, architects, engineers, developers -> /", "On-site full-time quality assurance team -> /about", "Tackles tough jobs other shops avoid -> /about", "Headquarters Fredericksburg, Virginia -> db", "Company name Dominion Steel LLC -> db", "Website http://www.dominionsteel.net/ -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Our in-house team handles every stage of production \u2014 estimati