UPDATE companies SET description='Double H Packaging, Inc., headquartered in Warminster, Pennsylvania, has been a family-owned business since its founding in 1974 by Harry Harp. The company began as a profile extrusion manufacturer producing plastic cores for the paper converting industry.

Today, Double H operates three manufacturing facilities — in Warminster, PA (cup forming), Marion, IN, and Morristown, TN (extrusion) — and offers a broad range of packaging processes. These include profile extrusion, rigid cup forming, thin-wall injection molding, in-mold labeling (IML), flexographic and offset printing, insert injection molding, and in-house prototyping via stereolithography (SLA) and powder-printed models. The company also provides tooling and mold making, pre-press services, and package design. Its product line spans cups and composite lids, thin-wall plastic containers, plastic cores, tubes, rails, paper/film/foil materials, labels, filtration components, and a plastic-free all-paper pint introduced in 2025.

Double H serves the food packaging sector, with explicit focus on snacks and convenience foods, ice cream and frozen desserts, and additional food packaging applications. Customers range from brands seeking off-the-shelf packaging to those requiring custom solutions tailored to specific brand needs.

The company emphasizes its family-owned heritage and commitment to quality products and workplace environment. Its differentiators include in-house prototyping, tooling, and mold-making for fast, precise development; a patented lid molding process dating to 1985; the 2012 acquisition of Old York Road Printing adding offset capabilities; and SQF certification for food safety management.', certifications=ARRAY['SQF']::text[], profile='{"capabilities": ["Profile extrusion", "Rigid cup forming", "Thin-wall injection molding", "In-mold labeling (IML)", "Flexographic printing", "Offset printing", "Insert injection molding", "Stereolithography (SLA) prototyping", "Powder-printed model prototyping", "Tooling and mold making", "Pre-press services", "Package design services", "Package and mold design", "Custom packaging solutions", "Paperboard printing", "Composite lid molding"], "industries": ["Snacks and convenience foods", "Ice cream and frozen desserts", "Food packaging", "Paper converting"], "materials": ["Plastic", "Paperboard", "Film", "Foil", "Paper"], "equipment": ["Stereolithography (SLA\u00ae) systems", "Powder-printed model systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1974", "In-house prototyping, tooling, and mold-making for fast development", "Custom packaging solutions tailored to specific brand needs", "Three manufacturing facilities in Pennsylvania, Indiana, and Tennessee", "SQF certified food safety management"], "facts_used": ["Founded 1974 by Harry Harp -> /about", "Family-owned since 1974 -> /about", "Headquarters Warminster, PA -> /about", "Facilities in Marion, IN and Morristown, TN -> /about", "Capabilities: extrusion, cup forming, thin wall injection molding, IML, flexographic printing, offset printing, prototyping, tooling & mold making, pre-press, package design -> /about", "Products: cups & composite lids, thin wall plastic packaging, plastic cores, tube/tubing, rails, paper/film/foil, labels, filtration, all paper pint -> /", "Industries: snacks & convenience foods, ice cream & frozen desserts, food packaging -> /", "Certification: SQF -> db", "Patented lid molding process 1985 -> /about", "Acquired Old York Road Printing 2012 -> /about", "Introduced plastic-free All Paper Pint 2025 -> /about", "Operating as Double H Packaging since 2025 -> /about", "Team members listed -> /about", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Double H began in 1974 as a family-owned profile extrusion manufacturer.", "founded_year": "1974", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/double-h-plastics-inc/"], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='double-h-packaging-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='DoubleButter is based in Denver, Colorado. The company’s name and philosophy originated from a casual remark by Dexter about preferring English muffins with both butter and peanut butter, a metaphor for the blend of complementary elements that defines its approach. While the exact founding year and ownership structure are not publicly disclosed, the business centers on collaborative furniture design and production.

